entries[205021] = { ["name"] = "Froststrahl", ["text"] = "2% von Grundmana 40 Meter Reichweite\nKanalisiert (Wirken in 5 sek.) 1 min Abklingzeit\nKanalisiert 5 Sek. lang einen Strahl eisiger Macht auf einen Gegner, der ihm alle 1 Sek. (269.1% der Zaubermacht) Frostschaden zufügt und ihn um 60% verlangsamt. Jedes Mal, wenn 'Froststrahl' Schaden verursacht, werden der Schaden und die Verlangsamung des Effekts um 10 % erhöht.\n\nErzeugt im Verlauf der Effektdauer 2 Aufladungen von 'Eisige Finger'." }
entries[205022] = { ["name"] = "Arkaner Familiar", ["text"] = "Das Wirken von 'Arkane Intelligenz' beschwört einen Familiar, der Eure Gegner angreift und Euer maximales Mana 1 Stunde lang um 10% erhöht." }
entries[205023] = { ["name"] = "Großbrand", ["text"] = "'Feuerball' und 'Pyroschlag' belegen das Ziel mit 'Großbrand', wodurch es im Verlauf von 8 Sek. zusätzlich (7.03868% der Zaubermacht) Feuerschaden erleidet.\n\nBei Gegnern, die von 'Großbrand' oder 'Entzünden' betroffen sind, besteht eine Chance von 15%, dass sie auflodern und Gegnern in der Nähe (6.28762% der Zaubermacht) Feuerschaden zufügen." }
