entries[205027] = { ["name"] = "Knochenkälte", ["text"] = "Immer wenn Ihr versucht, ein Ziel zu unterkühlen, gewinnt Ihr 'Knochenkälte' hinzu, wodurch Euer sämtlicher verursachter Zauberschaden für 8 Sek. um 0.5% erhöht wird. Dieser Effekt ist bis zu 10-mal stapelbar." }
