entries[205627] = { ["name"] = "Gezackte Stacheln", ["text"] = "Solange 'Dämonenstachel' aktiv ist, fügen alle gegen Euch gerichteten Nahkampfangriffe dem Angreifer körperlichen Schaden in Höhe von 30% Eures erlittenen Schadens zu." }
entries[205628] = { ["name"] = "Chaosregen", ["text"] = "Erhöht den Einschlagsradius von 'Infernoeinschlag' um 100% und verringert die Bewegungsgeschwindigkeit aller getroffenen Gegner für 5 Sek. um 50%." }
entries[205629] = { ["name"] = "Dämonisches Trampeln", ["text"] = "Sofort 20 sek. Abklingzeit\n1 Aufladung\nVerwandelt Euch in Dämonenform. Dadurch erhöht Ihr 3 Sek. lang Eure Bewegungsgeschwindigkeit um 175%, schlagt alle Gegner auf Eurem Weg nieder und fügt ihnen (10.7% der Angriffskraft) körperlichen Schaden zu.\n\nWährend 'Dämonisches Trampeln' aktiv ist, könnt Ihr zwar nicht verlangsamt werden, aber auch keine Zauber wirken oder normale Angriffe ausführen. Teilt sich Aufladungen mit 'Infernoeinschlag'." }
entries[205630] = { ["name"] = "Illidans Griff", ["text"] = "Ersetzt Teufelseruption\n15 Meter ReichweiteKanalisiert (Wirken in 5 sek.) 1 min Abklingzeit\nIhr nehmt das Ziel in einen dämonischen Würgegriff, betäubt es und haltet es fest, was im Verlauf von 5 Sek. (1120% der Angriffskraft) Schattenschaden verursacht, während das Ziel festgehalten wird. Kann sich während der Kanalisierung bewegen.\n\nMithilfe von 'Illidans Griff' schleudert Ihr das Ziel dann an einen Ort innerhalb von 20 Metern." }
entries[205631] = { ["name"] = "Verderbte Wunden", ["text"] = "25 Meter Reichweite\nSofort\nVom Schatten von Helya verwundet." }
entries[205635] = { ["name"] = "Leuchtpistole des Assassinen", ["text"] = "Wirken in 1 sek.\nIhr tragt eine Leuchtpistole, die bei Verwendung einen Assassinen herbeibeschwört, der Euer Ziel angreift." }
entries[205636] = { ["name"] = "Naturgewalt", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nBeschwört für 10 Sek. ein Wäldchen aus 3 Treants, die sofort Gegner im Zielgebiet verspotten und angreifen.\n\nErzeugt 20 Astrale Macht." }
