entries[205646] = { ["name"] = "Teufelsseelenspalten", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nFügt Gegnern in einem kegelförmigen Bereich von 10 Metern vor dem Zaubernden Chaosschaden zu und verringert ihre erhaltene Heilung 8 Sek. lang um 50%." }
entries[205647] = { ["name"] = "Schild", ["text"] = "100 Meter Reichweite\nSofort\nAlle Angriffe aus der Richtung, in die der Schild zeigt, werden abgewehrt." }
entries[205648] = { ["name"] = "Windzorn", ["text"] = "Sofort\nVerzaubert Eure Waffenhandwaffe für 1 Stunde mit dem Element des Windes. Jeder Angriff mit der Waffenhandwaffe hat eine Chance von 25%, [ Wilde Winde : drei / zwei] zusätzliche Angriffe auszulösen, die jeweils (27.945% der Angriffskraft)% körperlichen Schaden verursachen. [ Kraftvolle Winde : Durch 'Windzorn' erhöht jeder Windzornangriff in Folge innerhalb von 15 Sek. den Schaden von 'Windzorn' um 15%. Bis zu 5-mal stapelbar ]" }
entries[205649] = { ["name"] = "Teuflischer Ausstoß", ["text"] = "Sofort\nErschafft eine Kugel aus Teufelsenergie, die aufbricht und Geschosse auf mehrere Spielercharaktere abfeuert, die sofort 15805 Feuerschaden sowie 8 Sek. lang alle 2 Sek. 12802 Feuerschaden erleiden. Immer wenn dieser Effekt Schaden verursacht, wird außerdem eine Teufelsflammenlache erschaffen." }
entries[205650] = { ["name"] = "Belebt" }
entries[205653] = { ["name"] = "Zeitenfluss", ["text"] = "100 Meter Reichweite\nSofort\nDer Zeitstrom in der Nähe des Nachtbrunnens ist in stetiger Veränderung. Diese Veränderungen betreffen das Wirken von Zaubern, die Bewegungsgeschwindigkeit und das Angriffstempo. Regelmäßige Effekte und Abklingzeiten sind ebenfalls davon betroffen." }
