entries[206221] = { ["name"] = "Mächtige Teufelsfesseln", ["text"] = "Wirken in 2 sek.\nFesselt ein Ziel an einen Ort, nachdem es zurückgestoßen wurde. Zudem werden Ziele um 70% verlangsamt und erleiden alle 0,5 Sek. 1106 Feuerschaden. Wenn die Fesseln durchbrochen werden, explodieren sie und fügen Zielen innerhalb von 5 Metern um das gefesselte Ziel 173852 Feuerschaden zu. Dieser Schaden wird gleichmäßig unter allen getroffenen Zielen aufgeteilt." }
